function processInput(rawData) {
  // The input string that will be searched
  const targetString = rawData;

  // A list to store numbers generated by a specific pattern
  let numberList = [];

  // Populate the numberList with multiples of 2019, from 2019*1 up to 2019*99
  for (let idxA = 1; idxA < 100; idxA++) {
    numberList.push(2019 * idxA);
  }

  // A string to accumulate markers for each number found in the target string
  let foundMarkers = '';

  // Iterate through each generated number in the numberList
  for (let idxB = 0; idxB < numberList.length; idxB++) {
    // Get the current number to use as a search pattern
    let currentPatternNum = numberList[idxB];

    // Create a global regular expression to find all occurrences of the current number
    // The number is converted to a string for the regex pattern
    let foundOccurrences = targetString.match(new RegExp(`${currentPatternNum}`, 'g'));

    // Check if any matches were found. If 'match' returns null, treat it as an empty string
    // to safely check its length.
    if ((foundOccurrences || '').length > 0) {
      foundMarkers += '#'; // Append a hash marker for each number that has at least one match
    }
  }

  // Output the total count of unique numbers (from the generated list) that were found
  // in the target string. This is represented by the length of the foundMarkers string.
  console.log(foundMarkers.length);
}

// Read the input from standard input and pass it to the processing function
processInput(require('fs').readFileSync('/dev/stdin', 'utf8'));
